import React, { useState, useEffect } from 'react';
import { useWidgetDraggable, useWidgetResizable, useWidgetPersistence, useWidgetAI } from '../hooks/useWidgetHooks';
import '../styles/NotepadWidget.css';

const NotepadWidget = () => {
  const widgetId = 'notepad-widget';
  const draggable = useWidgetDraggable(widgetId);
  const resizable = useWidgetResizable(widgetId, { width: 450, height: 550 });
  const { data: notepadData, updateData } = useWidgetPersistence(widgetId, {
    notes: [],
    aiSummaries: [],
  });
  const { callGemini, loading: aiLoading } = useWidgetAI();

  const [activeTab, setActiveTab] = useState('notes');
  const [notes, setNotes] = useState(notepadData.notes || []);
  const [aiSummaries, setAiSummaries] = useState(notepadData.aiSummaries || []);
  const [newNoteText, setNewNoteText] = useState('');
  const [editingId, setEditingId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [showDualPane, setShowDualPane] = useState(false);
  const [selectedNote, setSelectedNote] = useState(null);

  // Add new note
  const addNote = () => {
    if (newNoteText.trim()) {
      const note = {
        id: Date.now(),
        text: newNoteText,
        timestamp: new Date().toLocaleString(),
        charCount: newNoteText.length,
      };
      const updatedNotes = [note, ...notes];
      setNotes(updatedNotes);
      updateData((prev) => ({ ...prev, notes: updatedNotes }));
      setNewNoteText('');
    }
  };

  // Delete note
  const deleteNote = (id) => {
    const updatedNotes = notes.filter((n) => n.id !== id);
    setNotes(updatedNotes);
    updateData((prev) => ({ ...prev, notes: updatedNotes }));
  };

  // Update note
  const updateNote = (id, newText) => {
    const updatedNotes = notes.map((n) =>
      n.id === id ? { ...n, text: newText, charCount: newText.length, timestamp: new Date().toLocaleString() } : n
    );
    setNotes(updatedNotes);
    updateData((prev) => ({ ...prev, notes: updatedNotes }));
  };

  // AI Summarize single note
  const summarizeSingleNote = async (noteText) => {
    const prompt = `Summarize this note concisely in 2-3 sentences, highlighting the main points:

"${noteText}"

Keep it clear and organized.`;

    const result = await callGemini(prompt);
    if (result.success) {
      return result.content;
    }
    return null;
  };

  // AI Summarize all notes
  const summarizeAllNotes = async () => {
    const allText = notes.map((n) => n.text).join('\n\n');
    const prompt = `Analyze and summarize all these notes into key takeaways:

${allText}

Provide:
1. Main themes (top 3)
2. Key points to remember
3. Suggested actions
4. Overall summary

Keep it concise and well-organized.`;

    const result = await callGemini(prompt);
    if (result.success) {
      const summary = {
        id: Date.now(),
        content: result.content,
        timestamp: new Date().toLocaleString(),
        noteCount: notes.length,
      };
      const updatedSummaries = [summary, ...aiSummaries];
      setAiSummaries(updatedSummaries);
      updateData((prev) => ({ ...prev, aiSummaries: updatedSummaries }));
    }
  };

  // Filter notes by search
  const filteredNotes = notes.filter((n) =>
    n.text.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Export notes
  const exportNotes = () => {
    const content = notes.map((n) => `${n.timestamp}\n${n.text}\n`).join('\n---\n');
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'notes.txt';
    a.click();
  };

  // Import notes
  const importNotes = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const text = event.target.result;
        const lines = text.split('---');
        const importedNotes = lines
          .filter((l) => l.trim())
          .map((l) => ({
            id: Date.now() + Math.random(),
            text: l.trim(),
            timestamp: new Date().toLocaleString(),
            charCount: l.length,
          }));
        const updatedNotes = [...importedNotes, ...notes];
        setNotes(updatedNotes);
        updateData((prev) => ({ ...prev, notes: updatedNotes }));
      };
      reader.readAsText(file);
    }
  };

  return (
    <div
      {...draggable}
      ref={draggable.ref}
      {...resizable}
      className="widget-container notepad-widget"
      style={{
        ...draggable.style,
        ...resizable.style,
        position: 'fixed',
        zIndex: 1000,
        background: 'radial-gradient(ellipse at 30% 50%, #0C294F 0%, #061D3B 70%, #041529 100%)',
        border: '1px solid rgba(0, 255, 136, 0.4)',
        borderRadius: '12px',
        boxShadow: '0 0 20px rgba(0, 255, 136, 0.3), inset 0 0 15px rgba(0, 255, 136, 0.1)',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      {/* Corner Brackets */}
      <div style={{
        position: 'absolute',
        top: '-6px',
        left: '-6px',
        width: '16px',
        height: '16px',
        borderTop: '2px solid rgba(255, 255, 255, 0.9)',
        borderLeft: '2px solid rgba(255, 255, 255, 0.9)',
        zIndex: 1,
      }} />
      <div style={{
        position: 'absolute',
        bottom: '-6px',
        right: '-6px',
        width: '16px',
        height: '16px',
        borderBottom: '2px solid rgba(255, 255, 255, 0.9)',
        borderRight: '2px solid rgba(255, 255, 255, 0.9)',
        zIndex: 1,
      }} />

      {/* Widget Controls - Hover Buttons */}
      <div
        className="widget-controls"
        style={{
          position: 'absolute',
          top: '-8px',
          right: '-8px',
          display: 'none',
          gap: '6px',
          zIndex: 10,
          padding: '4px',
          background: 'rgba(12, 41, 79, 0.3)',
          borderRadius: '8px',
          backdropFilter: 'blur(10px)',
          border: '1px solid rgba(0, 255, 136, 0.2)',
          boxShadow: '0 4px 12px rgba(0, 0, 0, 0.4)',
        }}
        onMouseEnter={(e) => e.currentTarget.style.display = 'flex'}
      >
        <button
          title="Make Bigger"
          style={{
            width: '20px',
            height: '20px',
            background: 'linear-gradient(135deg, rgba(0, 100, 50, 0.9) 0%, rgba(0, 150, 75, 0.95) 100%)',
            border: '1px solid rgba(0, 255, 150, 0.6)',
            borderRadius: '6px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '10px',
            color: 'rgba(0, 255, 150, 1)',
            fontWeight: 'bold',
            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
            userSelect: 'none',
            position: 'relative',
            backdropFilter: 'blur(8px)',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1)',
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'scale(1.1) translateY(-1px)';
            e.target.style.borderColor = 'rgba(0, 255, 150, 1)';
            e.target.style.boxShadow = '0 4px 15px rgba(0, 255, 150, 0.4), 0 0 20px rgba(0, 255, 150, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'scale(1) translateY(0)';
            e.target.style.borderColor = 'rgba(0, 255, 150, 0.6)';
            e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1)';
          }}
          onClick={() => {
            // Make widget bigger logic
            const currentSize = widgetSize || 'normal';
            const sizes = { small: 'normal', normal: 'large', large: 'xlarge' };
            setWidgetSize(sizes[currentSize] || 'large');
          }}
        >
          ⧨
        </button>
        <button
          title="Make Smaller"
          style={{
            width: '20px',
            height: '20px',
            background: 'linear-gradient(135deg, rgba(100, 50, 0, 0.9) 0%, rgba(150, 75, 0, 0.95) 100%)',
            border: '1px solid rgba(255, 150, 0, 0.6)',
            borderRadius: '6px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '10px',
            color: 'rgba(255, 180, 0, 1)',
            fontWeight: 'bold',
            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
            userSelect: 'none',
            position: 'relative',
            backdropFilter: 'blur(8px)',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1)',
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'scale(1.1) translateY(-1px)';
            e.target.style.borderColor = 'rgba(255, 150, 0, 1)';
            e.target.style.boxShadow = '0 4px 15px rgba(255, 150, 0, 0.4), 0 0 20px rgba(255, 150, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'scale(1) translateY(0)';
            e.target.style.borderColor = 'rgba(255, 150, 0, 0.6)';
            e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1)';
          }}
          onClick={() => {
            // Make widget smaller logic
            const currentSize = widgetSize || 'normal';
            const sizes = { xlarge: 'large', large: 'normal', normal: 'small' };
            setWidgetSize(sizes[currentSize] || 'small');
          }}
        >
          ⧩
        </button>
        <button
          title="Close"
          style={{
            width: '20px',
            height: '20px',
            background: 'linear-gradient(135deg, rgba(100, 20, 20, 0.9) 0%, rgba(150, 30, 30, 0.95) 100%)',
            border: '1px solid rgba(255, 80, 80, 0.6)',
            borderRadius: '6px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '10px',
            color: 'rgba(255, 100, 100, 1)',
            fontWeight: 'bold',
            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
            userSelect: 'none',
            position: 'relative',
            backdropFilter: 'blur(8px)',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1)',
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'scale(1.1) translateY(-1px)';
            e.target.style.borderColor = 'rgba(255, 80, 80, 1)';
            e.target.style.boxShadow = '0 4px 15px rgba(255, 80, 80, 0.4), 0 0 20px rgba(255, 80, 80, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'scale(1) translateY(0)';
            e.target.style.borderColor = 'rgba(255, 80, 80, 0.6)';
            e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1)';
          }}
          onClick={() => {
            // Close widget logic
            setIsVisible(false);
          }}
        >
          ⧬
        </button>
      </div>
      {/* Header */}
      <div className="widget-header" style={{ borderBottom: '1px solid rgba(0, 255, 136, 0.3)', padding: '12px' }}>
        <div className="widget-title" style={{ color: 'rgba(0, 255, 136, 1)', fontSize: '16px', fontWeight: 'bold' }}>
          📝 NOTEPAD WIDGET
        </div>
        <div className="widget-status" style={{ fontSize: '11px', color: 'rgba(0, 200, 136, 0.8)' }}>
          ● {notes.length} NOTES
        </div>
      </div>

      {/* Tabs */}
      <div className="notepad-tabs" style={{ display: 'flex', borderBottom: '1px solid rgba(0, 255, 136, 0.3)', gap: '8px', padding: '8px' }}>
        {['notes', 'summaries'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            style={{
              background: activeTab === tab ? 'rgba(0, 255, 136, 0.8)' : 'transparent',
              color: activeTab === tab ? '#0a0e27' : 'rgba(0, 255, 136, 0.9)',
              border: '1px solid rgba(0, 255, 136, 0.6)',
              padding: '6px 12px',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '12px',
              fontWeight: activeTab === tab ? 'bold' : 'normal',
            }}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {/* Content Area */}
      <div
        className="notepad-content"
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '12px',
          color: 'rgba(0, 255, 136, 0.9)',
          fontSize: '12px',
        }}
      >
        {activeTab === 'notes' && (
          <div className="notes-section">
            {/* Add Note Form */}
            <div style={{ marginBottom: '12px' }}>
              <textarea
                value={newNoteText}
                onChange={(e) => setNewNoteText(e.target.value)}
                placeholder="Write a new note..."
                style={{
                  width: '100%',
                  height: '80px',
                  padding: '8px',
                  backgroundColor: 'rgba(0, 20, 0, 0.8)',
                  border: '1px solid rgba(0, 255, 136, 0.4)',
                  color: 'rgba(0, 255, 136, 0.9)',
                  borderRadius: '4px',
                  fontSize: '12px',
                  resize: 'none',
                  boxShadow: 'inset 0 0 5px rgba(0, 255, 136, 0.1)'
                }}
              />
              <div style={{ display: 'flex', gap: '8px', marginTop: '8px' }}>
                <button
                  onClick={addNote}
                  style={{
                    flex: 1,
                    padding: '6px',
                    backgroundColor: 'rgba(0, 255, 136, 0.8)',
                    color: '#0a0e27',
                    border: 'none',
                    borderRadius: '3px',
                    cursor: 'pointer',
                    fontWeight: 'bold',
                    fontSize: '11px',
                  }}
                >
                  Add Note
                </button>
                <button
                  onClick={() => setNewNoteText('')}
                  style={{
                    padding: '6px 12px',
                    backgroundColor: 'transparent',
                    border: '1px solid rgba(0, 255, 136, 0.6)',
                    color: 'rgba(0, 255, 136, 0.9)',
                    borderRadius: '3px',
                    cursor: 'pointer',
                    fontSize: '11px',
                  }}
                >
                  Clear
                </button>
              </div>
              <div style={{ fontSize: '10px', color: 'rgba(0, 200, 136, 0.8)', marginTop: '4px' }}>
                Characters: {newNoteText.length}
              </div>
            </div>

            {/* Search */}
            <input
              type="text"
              placeholder="Search notes..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                width: '100%',
                padding: '8px',
                marginBottom: '10px',
                backgroundColor: 'rgba(0, 20, 0, 0.8)',
                border: '1px solid rgba(0, 255, 136, 0.4)',
                color: 'rgba(0, 255, 136, 0.9)',
                borderRadius: '4px',
                fontSize: '12px',
                boxShadow: 'inset 0 0 5px rgba(0, 255, 136, 0.1)'
              }}
            />

            {/* Notes List */}
            {filteredNotes.length === 0 ? (
              <div style={{ color: 'rgba(0, 200, 136, 0.8)', textAlign: 'center', padding: '20px' }}>
                No notes yet. Start typing!
              </div>
            ) : (
              filteredNotes.map((note) => (
                <div key={note.id} style={{ marginBottom: '10px', borderBottom: '1px solid rgba(0, 255, 136, 0.2)', paddingBottom: '8px' }}>
                  <div style={{ fontSize: '10px', color: 'rgba(0, 200, 136, 0.8)' }}>{note.timestamp}</div>
                  {editingId === note.id ? (
                    <textarea
                      value={note.text}
                      onChange={(e) => updateNote(note.id, e.target.value)}
                      style={{
                        width: '100%',
                        height: '60px',
                        padding: '6px',
                        backgroundColor: 'rgba(0, 20, 0, 0.8)',
                        border: '1px solid rgba(0, 255, 136, 0.4)',
                        color: 'rgba(0, 255, 136, 0.9)',
                        borderRadius: '3px',
                        fontSize: '11px',
                        marginTop: '4px',
                        boxShadow: 'inset 0 0 5px rgba(0, 255, 136, 0.1)'
                      }}
                    />
                  ) : (
                    <div style={{ color: '#cccccc', fontSize: '11px', margin: '4px 0', wordWrap: 'break-word' }}>
                      {note.text}
                    </div>
                  )}
                  <div style={{ fontSize: '10px', color: 'rgba(0, 200, 136, 0.8)', margin: '4px 0' }}>
                    {note.charCount} chars
                  </div>
                  <div style={{ display: 'flex', gap: '6px', marginTop: '4px' }}>
                    <button
                      onClick={() => setEditingId(editingId === note.id ? null : note.id)}
                      style={{
                        padding: '3px 8px',
                        fontSize: '10px',
                        backgroundColor: 'rgba(0, 255, 136, 0.2)',
                        border: '1px solid rgba(0, 255, 136, 0.6)',
                        color: 'rgba(0, 255, 136, 0.9)',
                        borderRadius: '2px',
                        cursor: 'pointer',
                      }}
                    >
                      {editingId === note.id ? 'Done' : 'Edit'}
                    </button>
                    <button
                      onClick={() => deleteNote(note.id)}
                      style={{
                        padding: '3px 8px',
                        fontSize: '10px',
                        backgroundColor: 'rgba(255, 0, 0, 0.2)',
                        border: '1px solid rgba(255, 0, 0, 0.6)',
                        color: 'rgba(255, 0, 0, 0.9)',
                        borderRadius: '2px',
                        cursor: 'pointer',
                      }}
                    >
                      Delete
                    </button>
                    <button
                      onClick={async () => {
                        const summary = await summarizeSingleNote(note.text);
                        if (summary) alert('AI Summary:\n\n' + summary);
                      }}
                      style={{
                        padding: '3px 8px',
                        fontSize: '10px',
                        backgroundColor: 'rgba(255, 255, 0, 0.2)',
                        border: '1px solid rgba(255, 255, 0, 0.6)',
                        color: 'rgba(255, 255, 0, 0.9)',
                        borderRadius: '2px',
                        cursor: 'pointer',
                      }}
                    >
                      {aiLoading ? '...' : 'Summarize'}
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'summaries' && (
          <div className="summaries-section">
            <button
              onClick={summarizeAllNotes}
              disabled={notes.length === 0 || aiLoading}
              style={{
                width: '100%',
                padding: '10px',
                marginBottom: '12px',
                backgroundColor: aiLoading ? 'rgba(0, 255, 136, 0.4)' : 'rgba(0, 255, 136, 0.8)',
                color: '#0a0e27',
                border: 'none',
                borderRadius: '4px',
                fontWeight: 'bold',
                cursor: aiLoading || notes.length === 0 ? 'not-allowed' : 'pointer',
                fontSize: '12px',
              }}
            >
              {aiLoading ? 'Analyzing...' : 'Summarize All Notes'}
            </button>
            {aiSummaries.length === 0 ? (
              <div style={{ color: 'rgba(0, 200, 136, 0.8)', textAlign: 'center', padding: '20px' }}>
                No AI summaries yet. Click above to create one!
              </div>
            ) : (
              aiSummaries.map((summary) => (
                <div key={summary.id} style={{ marginBottom: '12px', borderBottom: '1px solid rgba(0, 255, 136, 0.2)', paddingBottom: '10px' }}>
                  <div style={{ fontSize: '10px', color: 'rgba(0, 200, 136, 0.8)' }}>
                    {summary.timestamp} · {summary.noteCount} notes analyzed
                  </div>
                  <div style={{ fontSize: '11px', color: '#cccccc', marginTop: '6px', whiteSpace: 'pre-wrap' }}>
                    {summary.content}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      {/* Footer Controls */}
      <div
        style={{
          borderTop: '1px solid rgba(0, 255, 136, 0.3)',
          padding: '8px',
          display: 'flex',
          gap: '6px',
          justifyContent: 'space-between',
        }}
      >
        <button
          onClick={exportNotes}
          style={{
            padding: '6px 8px',
            fontSize: '10px',
            backgroundColor: 'rgba(0, 255, 136, 0.2)',
            border: '1px solid rgba(0, 255, 136, 0.6)',
            color: 'rgba(0, 255, 136, 0.9)',
            borderRadius: '2px',
            cursor: 'pointer',
          }}
        >
          📥 Export
        </button>
        <label style={{ cursor: 'pointer' }}>
          <input type="file" accept=".txt" onChange={importNotes} style={{ display: 'none' }} />
          <span
            style={{
              padding: '6px 8px',
              fontSize: '10px',
              backgroundColor: 'rgba(0, 255, 136, 0.2)',
              border: '1px solid rgba(0, 255, 136, 0.6)',
              color: 'rgba(0, 255, 136, 0.9)',
              borderRadius: '2px',
              display: 'inline-block',
            }}
          >
            📤 Import
          </span>
        </label>
        <div style={{ fontSize: '10px', color: 'rgba(0, 200, 136, 0.8)', alignSelf: 'center' }}>
          {notes.length} notes
        </div>
      </div>

      {/* Resize Handle */}
      <div
        onMouseDown={resizable.onResizeStart}
        style={{
          width: '20px',
          height: '20px',
          position: 'absolute',
          bottom: '0',
          right: '0',
          cursor: 'nwse-resize',
          background: 'linear-gradient(135deg, transparent 50%, rgba(0, 255, 136, 0.8) 50%)',
          borderRadius: '0 0 8px 0',
        }}
      />
    </div>
  );
};

export default NotepadWidget;
